use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let jobs = input.as_array().unwrap();
    let quantum = input.as_u64().unwrap();
    let mut indices = Vec::new();
    let mut work = 0;
    let mut current_index = 0;

    for job in jobs {
        let job_value = job.as_i64().unwrap();
        if job_value < 0 {
            return Value::Null;
        }
        work += job_value;
        while work > 0 && current_index < jobs.len() && quantum > 0 {
            work -= jobs[current_index].as_i64().unwrap();
            indices.push(current_index as i64);
            current_index += 1;
            quantum -= 1;
        }
    }

    Value::Array(indices)
}
